// Una cola de juguete con las reglas de una cola de nube, sobre un reloj simulado (en segundos).
// No es el código de ningún proveedor: copia el mecanismo de plazo de visibilidad y cola de mensajes fallidos.
class Cola {
  constructor(nombre, { visibilidad = 30, maxRecepciones = 3, muertos = null } = {}) {
    Object.assign(this, { nombre, visibilidad, maxRecepciones, muertos });
    this.msgs = [];
  }
  enviar(cuerpo, t) { this.msgs.push({ cuerpo, visibleDesde: t, recepciones: 0 }); }
  recibir(t) {
    for (const m of this.msgs.filter(m => m.visibleDesde <= t)) {
      if (m.recepciones >= this.maxRecepciones) {      // ya se intentó demasiado: va a la cola de mensajes fallidos
        this.msgs.splice(this.msgs.indexOf(m), 1);
        this.muertos.enviar(m.cuerpo, t);
        console.log(`t=${String(t).padStart(3)}  ${m.cuerpo.id} pasa a ${this.muertos.nombre} tras ${m.recepciones} intentos`);
        continue;
      }
      m.recepciones++;
      m.visibleDesde = t + this.visibilidad;           // se esconde durante el plazo de visibilidad
      return { m, recibo: m.recepciones };
    }
    return null;
  }
  borrar(m, recibo) {                                  // solo vale con el recibo del último intento
    if (m.recepciones !== recibo || !this.msgs.includes(m)) return false;
    this.msgs.splice(this.msgs.indexOf(m), 1);
    return true;
  }
}

const muertos = new Cola("cola-de-fallidos");
const cola = new Cola("pedidos", { visibilidad: 30, maxRecepciones: 3, muertos });
cola.enviar({ id: "A", tarea: "normal" }, 0);
cola.enviar({ id: "B", tarea: "lenta" }, 0);     // tarda 40 s: más que el plazo de 30 s
cola.enviar({ id: "C", tarea: "venenosa" }, 0);  // siempre falla

const efectosSinCuidado = [], efectosIdempotentes = new Set();
const trabajadores = [{ libre: 0 }, { libre: 0 }];
const pendientes = []; // finales de tarea: { t, m, recibo, ok, id }

for (let t = 0; t <= 140; t++) {
  for (const p of pendientes.filter(p => p.t === t)) {
    if (!p.ok) { console.log(`t=${String(t).padStart(3)}  ${p.m.cuerpo.id} falla: no se borra, volverá a aparecer`); continue; }
    efectosSinCuidado.push(p.m.cuerpo.id);
    efectosIdempotentes.add(p.m.cuerpo.id);
    const borrado = cola.borrar(p.m, p.recibo);
    console.log(`t=${String(t).padStart(3)}  ${p.m.cuerpo.id} procesado; borrar con recibo ${p.recibo}: ${borrado ? "sí" : "NO (ya lo recibió otro)"}`);
  }
  for (const w of trabajadores) {
    if (w.libre > t) continue;
    const r = cola.recibir(t);
    if (!r) continue;
    const dur = r.m.cuerpo.tarea === "lenta" ? 40 : 2;
    w.libre = t + dur;
    console.log(`t=${String(t).padStart(3)}  recibe ${r.m.cuerpo.id} (intento ${r.recibo})`);
    pendientes.push({ t: t + dur, m: r.m, recibo: r.recibo, ok: r.m.cuerpo.tarea !== "venenosa" });
  }
}
console.log("Efectos sin cuidado:", efectosSinCuidado.join(","));
console.log("Efectos con idempotencia:", [...efectosIdempotentes].join(","));
console.log("En la cola de fallidos:", muertos.msgs.map(m => m.cuerpo.id).join(","));

// Un tema de juguete: quien publica no sabe quién escucha. Cada suscriptor tiene su propia cola.
class Cola {
  constructor(nombre) { this.nombre = nombre; this.msgs = []; }
  enviar(m) { this.msgs.push(m); }
  recibir() { return this.msgs.shift(); }
}
class Tema {
  constructor(nombre) { this.nombre = nombre; this.subs = []; }
  suscribir(cola, filtro = () => true) { this.subs.push({ cola, filtro }); }
  publicar(m) {
    let copias = 0;
    for (const s of this.subs) if (s.filtro(m)) { s.cola.enviar({ ...m }); copias++; }
    console.log(`publicado ${m.tipo}#${m.id} -> ${copias} copia(s)`);
  }
}

const mails = new Cola("mails"), avisos = new Cola("avisos-push"), auditoria = new Cola("auditoria");
const pedidos = new Tema("pedido-creado");
pedidos.suscribir(mails);
pedidos.suscribir(avisos, m => m.monto > 100);   // filtro: solo los pedidos grandes
pedidos.suscribir(auditoria);

pedidos.publicar({ tipo: "pedido", id: 1, monto: 40 });
pedidos.publicar({ tipo: "pedido", id: 2, monto: 250 });

for (const c of [mails, avisos, auditoria]) {
  console.log(c.nombre.padEnd(12), "tiene", c.msgs.length, "->", c.msgs.map(m => m.id).join(","));
}
// Si agregás otro suscriptor, quien publica no cambia ni una línea.
